metrics=[]
def m(name,formula,population,unit='ratio',missing='No applicable observations or denominator is zero.'):
 metrics.append(dict(id='llm_lab.'+name,formula=formula,population=population,unit=unit,missing=missing,scope='diagnostic_only_not_a_replacement_for_42_original_equations'))
m('completion_rate','completed / planned','All planned case/variant/repetition executions, including failed/cancelled/not_run; complete means selected scope finished.')
m('first_response_projection_rate','projected_first_delivered_reply / logical_calls_with_delivered_reply','First actually delivered reply per logical stage call; harmless wrapper normalization allowed, semantic repair excluded. Transport-only failures shown in completion/failure counts.')
m('repair_rate','logical_calls_with_semantic_repair / initiated_logical_calls','All initiated logical stage calls; report fallback/transport retries separately in trace.')
m('canonical_preservation_rate','mutation_outputs_with_exact_saved_canonical / completed_mutation_outputs','Mutation-stage comparisons against the same saved canonical input.')
m('mutation_list_consistency_rate','mutations_with_consistent_span_category_repair_and_surface / applicable_declared_mutations','Declared events judged against exact canonical/surface transformation; semantic judgments preserve basis/receipt, unknowns excluded with count. Extra actual defects reported separately.')
m('request_fulfillment_rate','satisfied_applicable_request_predicates / applicable_request_predicates','Topic/coherent level as labelled semantic predicates; exact speaker participation and requested categories/counts. Approximate word length is reported as observed deviation, never exact-equality predicate.')
m('word_length_relative_deviation','abs(actual_words - requested_words) / requested_words','Actual counted text excluding speaker labels; separate canonical/surface statistics. Positive word target.')
m('detection_precision','TP / (TP + FP)','Frozen expected event correspondence per quality-case; duplicate claims merge under existing native mapping rules. TP=expected error events detected; FP=unsupported error assertions, including false correction of controls.')
m('detection_recall','TP / (TP + FN)','Same frozen expected population; FN=expected error events missed.')
m('detection_f1','2 * TP / (2 * TP + FP + FN)','Same reference event population; no zero-denominator perfection.')
m('category_accuracy','correct_reference_category_decisions / applicable_reference_category_decisions','Expected accepted primary/alternative IDs for localized mapped events; secondary labels never add detection events.')
m('repair_accuracy','correct_applicable_repair_propositions / applicable_reference_repair_propositions','Existing context-supported valid repair and native credit propositions; no string equality requirement.')
m('explanation_accuracy','correct_applicable_explanation_propositions / applicable_reference_explanation_propositions','Existing required/forbidden rationale propositions and actual expected basis.')
m('score_mae_pp','sum(abs(predicted_percent - reference_percent)) / paired_reference_scores','Applicable paired backend scores with frozen same policy/key/reference, computed from original native fractions; unknown references excluded explicitly.','percentage_points')
m('feedback_grounding_rate','supported_factual_items_or_correctly_labelled_practice / applicable_feedback_items','Frozen mutation key/actual scoring findings and semantic rubric. LLM judgment labelled llm_judged, not independent empirical truth.')
m('audio_target_confirmation_rate','actually_supported_target_realizations / targets_with_relevant_actual_observation','Relevant native/measured/audio-capable observations of rendered targets; text-only judgments and requested IPA are excluded with reason.')
m('latency_p50_ms','sorted_observed_duration_ms[ceil(0.50*n)-1]','n actual completed or failed call durations; report n and failures, cache hits excluded.','milliseconds')
m('latency_p95_ms','sorted_observed_duration_ms[ceil(0.95*n)-1]','Same observed latency population, nearest-rank quantile.','milliseconds')
m('reported_tokens_total','sum(reported_input_tokens + reported_output_tokens)','All actual attempt receipts; input includes cached tokens, do not add cached again. Reasoning included according to documented provider usage, never twice. Any required unknown component yields null total with known subtotal.','tokens')
m('cost_total_usd','sum(actual_cost_micro_usd) / 1000000','All real attempt costs under saved pricing/basis; any unknown cost yields null total with known subtotal. Cache inspections are not new calls.','USD')
m('repeat_detection_jaccard','mean(size(A intersection B) / size(A union B))','All unordered completed repetition pairs for same case/variant over normalized detected event sets. Both empty sets have similarity1; no pairs gives N/A. Preserve pair/sample denominator.')
m('leaf_macro_recall','sum(observed_leaf_recall) / observed_applicable_leaves','Equal-weight mean over reference-error leaves with actual positive error denominator. Report per-leaf counts and excluded/missing leaves across all122; controls reported separately.')
save(V/'domain/llm-quality-metrics.v1.json',dict(version='1.0.0',authority='docs/llm-lab.md',arithmetic='Exact native integers/decimals/ratios; MLflow floats are diagnostic displays. No hidden rounding before aggregation.',zero_denominator='N/A with reason',unknown='Unknown observations are not zero; retain known subtotals and applicability/exclusion counts.',paired_comparison='candidate-baseline on identical applicable completed case/expectation/repetition identities; also show full planned completion/error counts. Mean paired delta uses n paired samples; latency quantile delta compares named quantiles, not mean of per-row quantiles.',metrics=metrics))
